#!/usr/bin/env Rscript
source('Figure/_shared/current.R')
source(file.path(module_dir,'style.R'));source(file.path(module_dir,'data.R'));source(file.path(module_dir,'assemble.R'))
ids <- c('strong_action_prevalence','ranking_capture','stable_review_context','analytical_annotation_gaps')
for(id in ids) source(file.path(module_dir,'panels',id,'plot.R'))
input <- read_policy_concordance_input(list(row_count=as.integer(lock$ranked)),config)
prepared <- prepare_policy_concordance_data(input,config)
plots <- lapply(setNames(ids,ids),function(id) get(paste0('plot_policy_',id))(prepared$source_data[[id]],config))
save_nested(prepared$source_data);save_nested(prepared$audit_tables)
save_facts(c(prepared$statistics,list(full_inventory=lock$total,cohort='Fixed baseline rankable population, including partial evidence; missing components contribute zero.',capture_ties='Linear interpolation within tied-score groups; expected capture at matched screening size, not the official inclusive Top-N selection.',interval='Wilson 95% intervals for proportions; log-Wald 95% intervals for odds ratios.',strong_action_statuses=config$strong_action_statuses,stability_thresholds=config$thresholds)))
save_plot(assemble_policy_concordance_and_review_gaps(plots,config),183,150)
